select energy_manager.load_cards($cards$[
{"id":"p4-b15-022","paper":4,"topic":"Textile energy performance","kind":"problem","front":"A stenter handles 1000 kg/h of cloth with 50% inlet and 5% outlet moisture. Cloth enters at 28 °C and leaves at 80 °C. The stenter uses 1000 kg/h of steam at 660 kcal/kg with condensate at 90 °C, and latent heat is 540 kcal/kg. Find the overall thermal efficiency of the dryer.","back":"About 49% (the book's answer).","explain":"Dryer efficiency is the useful drying heat divided by the steam heat input. The steam supplies about 570,000 kcal/h and the useful drying work is about 280,000 kcal/h.","flash":false,"source":"BEE Book 4 Ch 15 p323","steps":[{"prompt":"Split the feed into water and bone-dry cloth, and find the inlet moisture.","answer":"1000 × 0.50 = 500 kg/h water and 1000 × 0.50 = 500 kg/h bone-dry cloth. Inlet moisture = 500 / 500 = 1.0 kg moisture per kg bone-dry material.","explain":"The formula uses moisture as kg per kg of bone-dry material, so the feed must be split before the ratio is taken."},{"prompt":"Find the moisture left in the product and the outlet moisture ratio.","answer":"Moisture in product = 500 × 0.05 / 0.95 = 26.3 kg/h. Outlet moisture = 26.3 / 500 = 0.053 kg per kg bone-dry material.","explain":"A product at 5% moisture holds 5 parts water in 95 parts dry matter, which is why the 0.95 divisor is used."},{"prompt":"Compute the useful drying heat.","answer":"W × (m_in − m_out) × ((T_out − T_in) + 540) = 500 × (1 − 0.053) × ((80 − 28) + 540) = 500 × 0.947 × 592 ≈ 280,312 kcal/h.","explain":"The 540 kcal/kg latent heat term is the energy to evaporate the moisture, and the temperature rise of the cloth is added in the same bracket as printed in the chapter."},{"prompt":"Find the heat input from the steam.","answer":"Q_in = 1000 × (660 − 90) = 570,000 kcal/h.","explain":"The steam gives up its enthalpy above the condensate enthalpy, which leaves at 90 °C."},{"prompt":"Compute the efficiency.","answer":"280,312 / 570,000 × 100 ≈ 49.2%.","explain":"Only about half of the steam heat is counted as useful drying heat in this example."}],"order":4636},
{"id":"p4-b15-023","paper":4,"topic":"Textile energy performance","kind":"fact","front":"What is the typical liquor (bath) ratio range in aqueous dyeing?","back":"1:4, 1:6 to 1:10, or higher, meaning kg of fabric to litres of water.","explain":"A higher liquor ratio means more water must be heated, so more steam is used per kg of cloth. The ratio depends on whether the dyeing is batch or continuous.","flash":false,"source":"BEE Book 4 Ch 15 p324","order":4637},
{"id":"p4-b15-024","paper":4,"topic":"Textile energy performance","kind":"fact","front":"What allowance does the chapter add for fabric and other losses in a dyeing steam balance?","back":"Add 10% on top of the liquor heat duty (M × Cp × ΔT) to cover fabric and other losses.","explain":"The chapter calls the heat absorbed by the fabric and vessel, radiation and vapours small and tedious to calculate. A 10% allowance is used instead, as in Example 15.2.","flash":false,"source":"BEE Book 4 Ch 15 p325","order":4638},
{"id":"p4-b15-025","paper":4,"topic":"Textile energy performance","kind":"problem","front":"100 kg of fabric is dyed in a jigger at liquor ratio 1:6. The liquor is heated from 30 to 80 °C. Steam is at 2 kg/cm² (g), enthalpy 650 kcal/kg. Find the steam quantity and the specific steam consumption, allowing 10% for fabric and other losses.","back":"About 50.8 kg of steam (the book prints 50.76 kg), giving 0.51 kg steam per kg of cloth.","explain":"Steam supplies the heat to raise the bath temperature, plus the 10% allowance. Specific consumption is the steam used per kg of cloth, which is the figure used to compare dyeing performance.","flash":false,"source":"BEE Book 4 Ch 15 p325","steps":[{"prompt":"Find the water volume for the bath.","answer":"Liquor ratio 1:6 means 6 litres per kg, so 100 kg × 6 = 600 litres (about 600 kg) of water.","explain":"Water weight is used as the liquor mass, since its density is about 1 kg/L."},{"prompt":"Find the heat needed to raise the liquor temperature.","answer":"600 × 1 × (80 − 30) = 30,000 kcal.","explain":"Heat = liquor mass × specific heat of the liquor (1 kcal/kg°C for water) × temperature rise."},{"prompt":"Add the 10% allowance for fabric and other losses.","answer":"30,000 + 0.10 × 30,000 = 33,000 kcal.","explain":"The chapter adds this margin to cover heat taken by the fabric, vessel and surroundings."},{"prompt":"Find the steam mass.","answer":"33,000 / 650 ≈ 50.8 kg of steam (book: 50.76 kg).","explain":"Each kg of steam at 2 kg/cm² (g) gives 650 kcal, so the heat load is divided by this enthalpy."},{"prompt":"Find the specific steam consumption.","answer":"50.8 / 100 = 0.51 kg steam per kg of cloth.","explain":"Specific consumption lets a dye house compare its steam use across batches and machines."}],"order":4639},
{"id":"p4-b15-026","paper":4,"topic":"Textile energy performance","kind":"fact","front":"Name two advantages of a thermic fluid heater over a steam system.","back":"Closed-cycle operation with minimal losses, and non-pressurised operation near 250 °C (steam at a similar temperature needs about 40 kg/cm²). It also has no blowdown, condensate or flash-steam losses.","explain":"Thermic fluid acts as a heat carrier at low pressure, so there is no boiler pressure to manage. The chapter says these features give good thermal efficiency.","flash":false,"source":"BEE Book 4 Ch 15 p326","order":4640},
{"id":"p4-b15-027","paper":4,"topic":"Textile energy performance","kind":"fact","front":"What is the direct (input-output) method for thermic fluid heater efficiency?","back":"Efficiency (%) = heat output / heat input × 100. Heat output (kcal/h) = mass flow (kg/h) × specific heat (kcal/kg°C) × temperature difference (°C). Heat input (kcal/h) = fuel firing rate (kg/h) × GCV (kcal/kg).","explain":"The direct method needs only the useful heat in the thermic fluid and the fuel input, so it is quick to run. The indirect (heat-loss) method is covered as similar to the boiler test.","flash":false,"source":"BEE Book 4 Ch 15 p327","order":4641},
{"id":"p4-b15-028","paper":4,"topic":"Textile energy performance","kind":"problem","front":"A thermic fluid heater circulates 68 m³/h of fluid (density 826 kg/m³, specific heat 2.223 kJ/kg°C) from 200 to 212 °C. It burns fuel oil at 46 kg/h with GCV 10,000 kcal/kg. Find the heater efficiency by the direct method.","back":"About 77.8%.","explain":"The direct method compares the heat picked up by the thermic fluid with the heat content of the fuel. Output is about 3.58 lakh kcal/h against 4.6 lakh kcal/h input.","flash":false,"source":"BEE Book 4 Ch 15 p328","steps":[{"prompt":"Convert the specific heat to kcal units.","answer":"2.223 kJ/kg°C ÷ 4.187 = 0.531 kcal/kg°C.","explain":"1 kcal = 4.187 kJ, so the value is converted before it is used with kcal units."},{"prompt":"Find the mass flow of the fluid.","answer":"68 m³/h × 826 kg/m³ = 56,168 kg/h.","explain":"Volume flow is converted to mass flow using the fluid density."},{"prompt":"Find the heat output.","answer":"56,168 × 0.531 × (212 − 200) ≈ 357,900 kcal/h (book: 357,902.5).","explain":"Heat output = mass flow × specific heat × temperature rise across the heater."},{"prompt":"Find the heat input from the fuel.","answer":"46 kg/h × 10,000 kcal/kg = 460,000 kcal/h.","explain":"Heat input = fuel firing rate × gross calorific value."},{"prompt":"Compute the efficiency.","answer":"357,902.5 / 460,000 × 100 = 77.8%.","explain":"This is the direct-method efficiency; the chapter notes the indirect method is the boiler-style cross-check."}],"order":4642},
{"id":"p4-b15-029","paper":4,"topic":"Textile energy performance","kind":"fact","front":"How does an air washer humidify air?","back":"By adiabatic cooling: spray water evaporates into the air stream, lowering its dry-bulb temperature and raising its humidity.","explain":"The unit has banks of spray nozzles, a collecting tank, and an eliminator section with PVC blades (3 or 4 bends) that removes water droplets before the air is ducted to the humidified areas.","flash":true,"source":"BEE Book 4 Ch 15 p328","order":4643},
{"id":"p4-b15-030","paper":4,"topic":"Textile energy performance","kind":"fact","front":"What is the saturation efficiency formula for an air washer?","back":"Saturation efficiency (%) = (Entering air DBT − Leaving air DBT) / (Entering air DBT − Entering air WBT) × 100.","explain":"Higher saturation efficiency gives a lower leaving air temperature. That increases the temperature rise available in the department, which cuts the supply air quantity and fan power.","flash":false,"source":"BEE Book 4 Ch 15 p329","order":4644},
{"id":"p4-b15-031","paper":4,"topic":"Textile energy performance","kind":"fact","front":"What makes up the room sensible heat load in a textile department?","back":"Heat from machine kW load, lighting, solar gain through the insulated roof, occupancy, and heat from the supply air fan motors.","explain":"The sum of these gains sets the required supply air quantity. For detailed estimates the chapter refers the reader to the ASHRAE HVAC handbook.","flash":false,"source":"BEE Book 4 Ch 15 p329","order":4645},
{"id":"p4-b15-032","paper":4,"topic":"Textile energy performance","kind":"problem","front":"Summer design air at 40 °C DBT and 25 °C WBT enters an air washer with 95% saturation efficiency. Find the air temperature leaving the washer.","back":"25.75 °C.","explain":"The washer cools the air toward its wet-bulb temperature by the saturation efficiency fraction. The leaving condition is then the start point for the department's heat gain line on the psychrometric chart.","flash":false,"source":"BEE Book 4 Ch 15 p330","steps":[{"prompt":"Find the spread between entering DBT and WBT.","answer":"40 − 25 = 15 °C.","explain":"This is the maximum cooling the washer could give if it were fully saturated."},{"prompt":"Apply the saturation efficiency.","answer":"15 × 0.95 = 14.25 °C of cooling achieved.","explain":"The efficiency fraction is the share of the maximum possible cooling that the washer actually delivers."},{"prompt":"Find the leaving air DBT.","answer":"40 − 14.25 = 25.75 °C.","explain":"Leaving DBT = entering DBT minus the achieved cooling."}],"order":4646},
{"id":"p4-b15-033","paper":4,"topic":"Textile energy performance","kind":"fact","front":"How is the supply air quantity for a humidified department calculated?","back":"Supply air (m³/h) = room sensible heat load (kcal/h) / [specific heat of air (kcal/kg°C) × air density (kg/m³) × temperature rise of humidified air (°C)].","explain":"The temperature rise runs from the air-washer leaving condition along the department's heat gain line to its design relative humidity line. A larger allowable temperature rise means less supply air is needed.","flash":false,"source":"BEE Book 4 Ch 15 p331","order":4647},
{"id":"p4-b15-034","paper":4,"topic":"Textile energy performance","kind":"fact","front":"Why does fan energy dominate humidification systems, and what share does it take?","back":"Fans account for about 90% of humidification system energy.","explain":"Savings therefore depend on efficient fan operation, optimised air changes, lower duct pressure drop, and efficient fans and motors. Fan and duct performance is covered in Chapter 6 of the book.","flash":false,"source":"BEE Book 4 Ch 15 p331","order":4648},
{"id":"p4-b15-035","paper":4,"topic":"Textile energy performance","kind":"problem","front":"A spinning department has a sensible heat load of 10,03,000 kcal/h. The air temperature rises 8 °C in the department. Air density is 1.2 kg/m³ and specific heat is 0.24 kcal/kg°C. Find the supply air quantity.","back":"About 4,35,330 m³/h (about 4.35 lakh m³/h).","explain":"Supply air is the airflow needed to carry the sensible heat gain at the chosen temperature rise. The chapter's text calls the 0.24 'specific gravity', but it is used as the specific heat of air.","flash":false,"source":"BEE Book 4 Ch 15 p331","steps":[{"prompt":"Write the formula for supply air.","answer":"Supply air = room sensible heat load / (Cp × density × temperature rise).","explain":"The heat carried by the air equals airflow × Cp × density × temperature rise."},{"prompt":"Compute the denominator.","answer":"0.24 × 1.2 × 8 = 2.304 kcal per m³ of air.","explain":"Units are kcal/kg°C × kg/m³ × °C = kcal/m³, so dividing kcal/h gives m³/h."},{"prompt":"Divide the heat load by that value.","answer":"1,003,000 / 2.304 ≈ 435,330 m³/h.","explain":"This is the supply air quantity for the spinning department."}],"order":4649},
{"id":"p4-b15-036","paper":4,"topic":"Textile energy performance","kind":"problem","front":"A batch of 125 kg of fabric is dyed at liquor ratio 1:6.5 with a 10% margin for losses. The liquor is heated from 30 to 90 °C and steam enthalpy is 660 kcal/kg. Find the steam per batch and the specific steam consumption.","back":"About 81.25 kg of steam per batch, giving 0.65 kg steam per kg of cloth.","explain":"The fabric weight and temperatures are taken from the book's worked solution, because the question text in the OCR is partly unreadable. The method matches Example 15.2 with a 10% margin.","flash":false,"source":"BEE Book 4 Ch 15 p332","steps":[{"prompt":"Find the heat to raise the liquor.","answer":"125 × 6.5 × (90 − 30) = 48,750 kcal.","explain":"Liquor mass = fabric weight × liquor ratio (kg of water per kg of fabric)."},{"prompt":"Add the 10% margin.","answer":"48,750 × 1.10 = 53,625 kcal per batch.","explain":"The margin covers losses in the dyeing machine."},{"prompt":"Find the steam mass per batch.","answer":"53,625 / 660 = 81.25 kg per batch.","explain":"Each kg of steam at 660 kcal/kg supplies that much heat."},{"prompt":"Find the specific steam consumption.","answer":"81.25 / 125 = 0.65 kg steam per kg of cloth.","explain":"Specific consumption is used to compare steam use across liquor ratios."}],"order":4650},
{"id":"p4-b15-037","paper":4,"topic":"Textile energy performance","kind":"problem","front":"A thermic fluid heater of 15 lakh kcal/h capacity circulates 100 m³/h of fluid (density 830 kg/m³, specific heat 0.55 kcal/kg°C), with the fluid returning at 256 °C and leaving at 270 °C. It burns coal at 300 kg/h with GCV 3,500 kcal/kg. Find (i) the % loading, (ii) the efficiency, and (iii) whether five new 1 lakh kcal/h chambers can be added.","back":"(i) 42.6%; (ii) 60.9%; (iii) yes, the total duty of 11.39 lakh kcal/h is within the 15 lakh kcal/h capacity.","explain":"Loading compares the heat duty with rated capacity. The OCR prints the GCV unit as kcal/hr, but the solution uses kcal/kg.","flash":false,"source":"BEE Book 4 Ch 15 p332","steps":[{"prompt":"Find the heat duty of the heater.","answer":"100 × 830 × 0.55 × (270 − 256) = 639,100 kcal/h.","explain":"Duty = flow (kg/h) × specific heat × temperature drop of the fluid through the user loop."},{"prompt":"Find the % loading.","answer":"639,100 / 1,500,000 × 100 = 42.6%.","explain":"Loading is the duty as a share of the rated capacity."},{"prompt":"Find the heat input and the efficiency.","answer":"Input = 300 × 3,500 = 1,050,000 kcal/h. Efficiency = 639,100 / 1,050,000 × 100 = 60.9%.","explain":"The coal firing rate multiplied by its GCV gives the heat input."},{"prompt":"Find the duty after adding the five chambers.","answer":"639,100 + 5 × 100,000 = 1,139,100 kcal/h.","explain":"The new chamber duties add to the existing duty."},{"prompt":"Check against capacity.","answer":"1,139,100 is below 1,500,000 kcal/h, about 76% loading, so the heater can carry the extra load.","explain":"The check is against the heater's rated capacity, not against the fuel input."}],"order":4651},
{"id":"p4-b15-038","paper":4,"topic":"Textile energy performance","kind":"problem","front":"100 m³ per day of dye liquor leaves the plant at 90 °C and can be cooled to 40 °C. Raw water at 30 °C is to be heated to 60 °C from this heat. Specific heat is 1 kcal/kg°C and liquor density is 1000 kg/m³. How many kg per day of hot water at 60 °C can be obtained?","back":"About 1,66,667 kg per day (about 1.67 lakh kg/day).","explain":"This is a heat-balance calculation: heat given up by the liquor equals heat taken up by the water. The answer is not printed in the chapter, so it is built directly on the Q = m × Cp × ΔT formula, ignoring losses as the question assumes.","flash":false,"source":"BEE Book 4 Ch 15 p333","steps":[{"prompt":"Find the liquor mass per day.","answer":"100 m³ × 1000 kg/m³ = 100,000 kg/day.","explain":"Density converts the volume into mass."},{"prompt":"Find the heat available from the liquor.","answer":"100,000 × 1 × (90 − 40) = 5,000,000 kcal/day.","explain":"This is the heat released as the liquor cools from 90 °C to the 40 °C discharge limit."},{"prompt":"Find the heat needed per kg of raw water.","answer":"1 × (60 − 30) = 30 kcal/kg.","explain":"Each kg of raw water must rise from 30 °C to 60 °C."},{"prompt":"Find the hot water obtainable.","answer":"5,000,000 / 30 ≈ 166,667 kg/day.","explain":"Dividing the available heat by the heat needed per kg gives the mass of hot water."}],"order":4652},
{"id":"p4-b15-039","paper":4,"topic":"Textile energy performance","kind":"fact","front":"A textile unit burns 3000 tonnes of firewood a year for its boilers and thermic fluid heaters. Does that alone make it a designated consumer?","back":"Not by itself. Firewood must be converted to MTOE using its calorific value and added to the electricity use before comparing with the 3000 MTOE threshold.","explain":"The threshold is in MTOE, not tonnes, so the mass of firewood cannot be compared with it directly. The chapter's L-2 review question is set up this way to test that conversion.","flash":false,"source":"BEE Book 4 Ch 15 p333","order":4653},
{"id":"p4-b15-040","paper":4,"topic":"Textile energy performance","kind":"problem","front":"200 kg of fabric is dyed in a jigger at liquor ratio 1:6. The dye liquor is heated from 30 to 90 °C with a specific heat of 1 kcal/kg°C. How many kcal are needed to heat the liquor?","back":"72,000 kcal.","explain":"The chapter's energy balance starts from the heat needed to raise the liquor temperature. This question uses that formula directly, without the 10% allowance.","flash":false,"source":"BEE Book 4 Ch 15 p333","steps":[{"prompt":"Find the liquor volume.","answer":"200 kg × 6 = 1,200 litres of water.","explain":"Liquor ratio is litres of water per kg of fabric."},{"prompt":"Convert to liquor mass.","answer":"1,200 kg, taking the density as about 1 kg/L.","explain":"Water weight is used as liquor mass in the heat balance."},{"prompt":"Compute the heat required.","answer":"1,200 × 1 × (90 − 30) = 72,000 kcal.","explain":"Heat = mass × specific heat × temperature rise."}],"order":4654},
{"id":"p4-b15-041","paper":4,"topic":"Textile energy performance","kind":"problem","front":"Air enters an air washer at 35 °C DBT and 28 °C WBT, with a saturation efficiency of 90%. Find the air temperature leaving the washer.","back":"28.7 °C.","explain":"This uses the same method as the chapter's air washer example: leaving DBT = entering DBT − (DBT − WBT) × saturation efficiency.","flash":false,"source":"BEE Book 4 Ch 15 p333","steps":[{"prompt":"Find the spread between DBT and WBT.","answer":"35 − 28 = 7 °C.","explain":"This is the maximum cooling possible at full saturation."},{"prompt":"Find the cooling achieved.","answer":"7 × 0.90 = 6.3 °C.","explain":"Only 90% of the maximum cooling is delivered."},{"prompt":"Find the leaving air DBT.","answer":"35 − 6.3 = 28.7 °C.","explain":"Leaving DBT = entering DBT minus the cooling achieved."}],"order":4655}
]$cards$::jsonb);
